-- Mission 25 Part 12F: tenant-private lead, appointment, issued-estimate and customer-response observations.
-- This authority records advice only. It does not change imported or NorthStar operational records.

CREATE TABLE public.canonical_external_customer_outcome_consents (
 id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID NOT NULL REFERENCES public.organizations(id),
 crm_source_key TEXT NOT NULL CHECK(crm_source_key~'^[a-z0-9][a-z0-9._-]{1,63}$'),
 communication_source_key TEXT NOT NULL CHECK(communication_source_key~'^[a-z0-9][a-z0-9._-]{1,63}$'),
 revision BIGINT NOT NULL CHECK(revision BETWEEN 1 AND 10000), previous_id UUID,
 action TEXT NOT NULL CHECK(action IN ('grant','revoke')),
 crm_source_consent_id UUID, crm_source_consent_revision BIGINT, crm_source_consent_digest TEXT,
 communication_source_consent_id UUID, communication_source_consent_revision BIGINT, communication_source_consent_digest TEXT,
 actor_user_id UUID NOT NULL, membership_id UUID NOT NULL, auth_session_id UUID NOT NULL,
 reason TEXT NOT NULL CHECK(public.canonical_learning_text_valid(reason,2000)), confirmed BOOLEAN NOT NULL CHECK(confirmed),
 confirmation_version TEXT NOT NULL CHECK(confirmation_version='m25-external-customer-outcome-consent-v1'),
 request_key_hash TEXT NOT NULL CHECK(request_key_hash~'^[0-9a-f]{64}$'), request_digest TEXT NOT NULL CHECK(request_digest~'^[0-9a-f]{64}$'),
 canonical_digest TEXT NOT NULL CHECK(canonical_digest~'^[0-9a-f]{64}$'), created_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
 UNIQUE(organization_id,crm_source_key,communication_source_key,revision), UNIQUE(organization_id,actor_user_id,request_key_hash),
 UNIQUE(organization_id,crm_source_key,communication_source_key,id),
 FOREIGN KEY(organization_id,membership_id) REFERENCES public.organization_memberships(organization_id,id),
 FOREIGN KEY(organization_id,actor_user_id,auth_session_id) REFERENCES public.auth_sessions(organization_id,user_id,id),
 FOREIGN KEY(organization_id,crm_source_key,communication_source_key,previous_id)
  REFERENCES public.canonical_external_customer_outcome_consents(organization_id,crm_source_key,communication_source_key,id),
 CHECK((revision=1 AND previous_id IS NULL) OR (revision>1 AND previous_id IS NOT NULL)),
 CHECK((action='grant' AND crm_source_consent_id IS NOT NULL AND crm_source_consent_revision BETWEEN 1 AND 10000 AND crm_source_consent_digest~'^[0-9a-f]{64}$'
  AND communication_source_consent_id IS NOT NULL AND communication_source_consent_revision BETWEEN 1 AND 10000 AND communication_source_consent_digest~'^[0-9a-f]{64}$')
  OR (action='revoke' AND crm_source_consent_id IS NULL AND crm_source_consent_revision IS NULL AND crm_source_consent_digest IS NULL
   AND communication_source_consent_id IS NULL AND communication_source_consent_revision IS NULL AND communication_source_consent_digest IS NULL))
);

CREATE TABLE public.canonical_external_customer_outcome_observations (
 id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID NOT NULL REFERENCES public.organizations(id),
 crm_source_key TEXT NOT NULL CHECK(crm_source_key~'^[a-z0-9][a-z0-9._-]{1,63}$'),
 communication_source_key TEXT NOT NULL CHECK(communication_source_key~'^[a-z0-9][a-z0-9._-]{1,63}$'),
 estimate_id UUID NOT NULL, crm_estimate_reference TEXT NOT NULL CHECK(length(crm_estimate_reference) BETWEEN 1 AND 128 AND crm_estimate_reference~'^[!-~]+$'),
 communication_estimate_reference TEXT NOT NULL CHECK(communication_estimate_reference~'^ref_[0-9a-f]{64}$'),
 revision BIGINT NOT NULL CHECK(revision BETWEEN 1 AND 10000), previous_id UUID,
 consent_id UUID NOT NULL, consent_revision BIGINT NOT NULL CHECK(consent_revision BETWEEN 1 AND 10000), consent_digest TEXT NOT NULL CHECK(consent_digest~'^[0-9a-f]{64}$'),
 crm_match_id UUID NOT NULL, crm_match_revision BIGINT NOT NULL CHECK(crm_match_revision BETWEEN 1 AND 10000), crm_match_digest TEXT NOT NULL CHECK(crm_match_digest~'^[0-9a-f]{64}$'),
 communication_match_id UUID NOT NULL, communication_match_revision BIGINT NOT NULL CHECK(communication_match_revision BETWEEN 1 AND 10000), communication_match_digest TEXT NOT NULL CHECK(communication_match_digest~'^[0-9a-f]{64}$'),
 target_digest TEXT NOT NULL CHECK(target_digest~'^[0-9a-f]{64}$'), crm_manifest JSONB NOT NULL CHECK(jsonb_typeof(crm_manifest)='array'),
 communication_manifest JSONB NOT NULL CHECK(jsonb_typeof(communication_manifest)='array'), source_digest TEXT NOT NULL CHECK(source_digest~'^[0-9a-f]{64}$'),
 outcomes JSONB NOT NULL, actor_user_id UUID NOT NULL, membership_id UUID NOT NULL, auth_session_id UUID NOT NULL,
 reason TEXT NOT NULL CHECK(public.canonical_learning_text_valid(reason,2000)), confirmed BOOLEAN NOT NULL CHECK(confirmed),
 confirmation_version TEXT NOT NULL CHECK(confirmation_version='m25-external-customer-outcome-observation-v1'),
 calculation_version TEXT NOT NULL CHECK(calculation_version='m25-external-customer-outcome-v1'),
 request_key_hash TEXT NOT NULL CHECK(request_key_hash~'^[0-9a-f]{64}$'), request_digest TEXT NOT NULL CHECK(request_digest~'^[0-9a-f]{64}$'),
 canonical_digest TEXT NOT NULL CHECK(canonical_digest~'^[0-9a-f]{64}$'), created_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
 UNIQUE(organization_id,crm_source_key,communication_source_key,estimate_id,crm_estimate_reference,communication_estimate_reference,revision),
 UNIQUE(organization_id,actor_user_id,request_key_hash),
 UNIQUE(organization_id,crm_source_key,communication_source_key,estimate_id,crm_estimate_reference,communication_estimate_reference,id),
 FOREIGN KEY(organization_id,membership_id) REFERENCES public.organization_memberships(organization_id,id),
 FOREIGN KEY(organization_id,actor_user_id,auth_session_id) REFERENCES public.auth_sessions(organization_id,user_id,id),
 FOREIGN KEY(organization_id,crm_source_key,communication_source_key,consent_id)
  REFERENCES public.canonical_external_customer_outcome_consents(organization_id,crm_source_key,communication_source_key,id),
 FOREIGN KEY(organization_id,crm_source_key,communication_source_key,estimate_id,crm_estimate_reference,communication_estimate_reference,previous_id)
  REFERENCES public.canonical_external_customer_outcome_observations(organization_id,crm_source_key,communication_source_key,estimate_id,crm_estimate_reference,communication_estimate_reference,id),
 CHECK((revision=1 AND previous_id IS NULL) OR (revision>1 AND previous_id IS NOT NULL))
);
CREATE INDEX canonical_external_customer_outcomes_current_idx ON public.canonical_external_customer_outcome_observations(organization_id,crm_source_key,communication_source_key,estimate_id,crm_estimate_reference,communication_estimate_reference,revision DESC);

CREATE FUNCTION public.canonical_external_customer_outcome_immutable() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $$ BEGIN RAISE EXCEPTION 'Customer outcome history is immutable' USING ERRCODE='23514'; END $$;
CREATE TRIGGER canonical_external_customer_outcome_consents_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON public.canonical_external_customer_outcome_consents FOR EACH STATEMENT EXECUTE FUNCTION public.canonical_external_customer_outcome_immutable();
CREATE TRIGGER canonical_external_customer_outcome_observations_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON public.canonical_external_customer_outcome_observations FOR EACH STATEMENT EXECUTE FUNCTION public.canonical_external_customer_outcome_immutable();

CREATE FUNCTION public.canonical_external_customer_outcome_dimension_valid(value JSONB,dimension TEXT) RETURNS BOOLEAN
LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE allowed TEXT[];
BEGIN
 IF jsonb_typeof(value)<>'object' OR public.canonical_field_evidence_object_keys_exact(value,ARRAY['status','value','basis','occurredAt','endedAt','evidenceClass','reason']) IS NOT TRUE
  OR jsonb_typeof(value->'status')<>'string' OR value->>'status' NOT IN ('recorded','unavailable') THEN RETURN FALSE; END IF;
 IF value->>'status'='unavailable' THEN RETURN value->'value'='null'::jsonb AND value->'basis'='null'::jsonb AND value->'occurredAt'='null'::jsonb AND value->'endedAt'='null'::jsonb AND value->'evidenceClass'='null'::jsonb AND jsonb_typeof(value->'reason')='string' AND public.canonical_learning_text_valid(value->>'reason',500); END IF;
 allowed:=CASE dimension WHEN 'lead' THEN ARRAY['new','qualified','unqualified','won','lost','unknown'] WHEN 'appointment' THEN ARRAY['requested','scheduled','completed','canceled','no_show','unknown'] WHEN 'issuedEstimate' THEN ARRAY['issued','accepted','declined','questioned','expired','revoked','unknown'] ELSE ARRAY['request_estimate','schedule','reschedule','cancel','question','status_request','complaint','compliment','other','unknown','satisfied','neutral','dissatisfied'] END;
 RETURN jsonb_typeof(value->'value')='string' AND value->>'value'=ANY(allowed)
  AND jsonb_typeof(value->'basis')='string' AND ((dimension IN ('lead','appointment','issuedEstimate') AND value->>'basis'='source_recorded') OR (dimension='customerResponse' AND value->>'basis' IN ('customer_explicit','human_reviewed','explicit_customer_feedback','human_reviewed_explicit_feedback')))
  AND jsonb_typeof(value->'occurredAt')='string' AND pg_input_is_valid(value->>'occurredAt','timestamp with time zone')
  AND (value->'endedAt'='null'::jsonb OR (dimension='appointment' AND jsonb_typeof(value->'endedAt')='string' AND pg_input_is_valid(value->>'endedAt','timestamp with time zone')))
  AND jsonb_typeof(value->'evidenceClass')='string' AND value->>'evidenceClass' IN ('provider_recorded','documented','owner_confirmed')
  AND value->'reason'='null'::jsonb;
END $$;

CREATE FUNCTION public.canonical_external_customer_outcomes_valid(value JSONB) RETURNS BOOLEAN
LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,public,pg_temp AS $$
 SELECT jsonb_typeof(value)='object' AND public.canonical_field_evidence_object_keys_exact(value,ARRAY['lead','appointment','issuedEstimate','customerResponse'])
  AND public.canonical_external_customer_outcome_dimension_valid(value->'lead','lead')
  AND public.canonical_external_customer_outcome_dimension_valid(value->'appointment','appointment')
  AND public.canonical_external_customer_outcome_dimension_valid(value->'issuedEstimate','issuedEstimate')
  AND public.canonical_external_customer_outcome_dimension_valid(value->'customerResponse','customerResponse') $$;
ALTER TABLE public.canonical_external_customer_outcome_observations ADD CONSTRAINT canonical_external_customer_outcomes_valid_check CHECK(public.canonical_external_customer_outcomes_valid(outcomes));

CREATE FUNCTION public.canonical_external_customer_outcome_unavailable(reason_value TEXT) RETURNS JSONB
LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,public,pg_temp AS $$ SELECT jsonb_build_object('status','unavailable','value',NULL,'basis',NULL,'occurredAt',NULL,'endedAt',NULL,'evidenceClass',NULL,'reason',reason_value) $$;

CREATE FUNCTION public.canonical_external_customer_outcome_consent_projection(value public.canonical_external_customer_outcome_consents,crm_current JSONB,communication_current JSONB)
RETURNS JSONB LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
 SELECT jsonb_build_object('id',value.id,'crmSourceKey',value.crm_source_key,'communicationSourceKey',value.communication_source_key,'revision',value.revision,'previousId',value.previous_id,'action',value.action,
  'sourcePermissionsCurrent',COALESCE(value.action='grant' AND crm_current->>'id'=value.crm_source_consent_id::text AND crm_current->>'digest'=rtrim(value.crm_source_consent_digest) AND communication_current->>'id'=value.communication_source_consent_id::text AND communication_current->>'digest'=rtrim(value.communication_source_consent_digest),FALSE),
  'reason',value.reason,'confirmed',value.confirmed,'confirmationVersion',value.confirmation_version,'digest',rtrim(value.canonical_digest),'createdAt',value.created_at) $$;

CREATE FUNCTION public.canonical_external_customer_outcome_consent_guard() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE crm_current JSONB;communication_current JSONB;previous_row public.canonical_external_customer_outcome_consents%ROWTYPE;expected_digest TEXT;
BEGIN
 crm_current:=public.canonical_external_business_source_consent_basis(NEW.organization_id,'crm_field_service',NEW.crm_source_key);communication_current:=public.canonical_external_business_source_consent_basis(NEW.organization_id,'communication',NEW.communication_source_key);
 IF NEW.action='grant' AND (crm_current IS NULL OR communication_current IS NULL OR NEW.crm_source_consent_id<>(crm_current->>'id')::uuid OR NEW.crm_source_consent_revision<>(crm_current->>'revision')::bigint OR rtrim(NEW.crm_source_consent_digest)<>crm_current->>'digest' OR NEW.communication_source_consent_id<>(communication_current->>'id')::uuid OR NEW.communication_source_consent_revision<>(communication_current->>'revision')::bigint OR rtrim(NEW.communication_source_consent_digest)<>communication_current->>'digest') THEN RAISE EXCEPTION 'Customer outcome source permission invalid' USING ERRCODE='23514';END IF;
 IF NEW.revision>1 THEN SELECT * INTO previous_row FROM public.canonical_external_customer_outcome_consents WHERE organization_id=NEW.organization_id AND crm_source_key=NEW.crm_source_key AND communication_source_key=NEW.communication_source_key AND id=NEW.previous_id;IF previous_row.id IS NULL OR previous_row.revision+1<>NEW.revision THEN RAISE EXCEPTION 'Customer outcome consent revision invalid' USING ERRCODE='23514';END IF;END IF;
 expected_digest:=public.canonical_completion_digest(jsonb_build_object('organizationId',NEW.organization_id,'crmSourceKey',NEW.crm_source_key,'communicationSourceKey',NEW.communication_source_key,'revision',NEW.revision,'previousId',NEW.previous_id,'action',NEW.action,'crmSourceConsentId',NEW.crm_source_consent_id,'crmSourceConsentRevision',NEW.crm_source_consent_revision,'crmSourceConsentDigest',rtrim(NEW.crm_source_consent_digest),'communicationSourceConsentId',NEW.communication_source_consent_id,'communicationSourceConsentRevision',NEW.communication_source_consent_revision,'communicationSourceConsentDigest',rtrim(NEW.communication_source_consent_digest),'actorUserId',NEW.actor_user_id,'reason',NEW.reason,'confirmationVersion',NEW.confirmation_version,'requestDigest',rtrim(NEW.request_digest)));
 IF rtrim(NEW.canonical_digest)<>expected_digest THEN RAISE EXCEPTION 'Customer outcome consent digest invalid' USING ERRCODE='23514';END IF;RETURN NEW;
END $$;
CREATE TRIGGER canonical_external_customer_outcome_consent_guard BEFORE INSERT ON public.canonical_external_customer_outcome_consents FOR EACH ROW EXECUTE FUNCTION public.canonical_external_customer_outcome_consent_guard();

CREATE FUNCTION public.canonical_external_customer_outcome_basis(org UUID,crm_source TEXT,communication_source TEXT,estimate_value UUID,crm_reference TEXT,communication_reference_value TEXT)
RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE crm_consent JSONB;communication_consent JSONB;crm_source_basis RECORD;communication_source_basis RECORD;crm_match public.canonical_external_business_reference_matches%ROWTYPE;communication_match public.canonical_external_business_reference_matches%ROWTYPE;target_basis JSONB;issued_record public.canonical_external_crm_field_service_import_records%ROWTYPE;issued_total BIGINT;lead_total BIGINT;appointment_total BIGINT;response_total BIGINT;crm_records JSONB;communication_records JSONB;lead_value JSONB;appointment_value JSONB;issued_value JSONB;response_value JSONB;outcome_value JSONB;digest_value TEXT;
BEGIN
 crm_consent:=public.canonical_external_business_source_consent_basis(org,'crm_field_service',crm_source);communication_consent:=public.canonical_external_business_source_consent_basis(org,'communication',communication_source);
 IF crm_consent IS NULL OR communication_consent IS NULL THEN RETURN NULL; END IF;
 SELECT * INTO crm_source_basis FROM public.canonical_external_business_source_references(org,'crm_field_service',crm_source) s WHERE s.reference_kind='estimate' AND s.external_reference=crm_reference;
 SELECT * INTO communication_source_basis FROM public.canonical_external_business_source_references(org,'communication',communication_source) s WHERE s.reference_kind='estimate' AND s.external_reference=communication_reference_value;
 IF crm_source_basis.source_digest IS NULL OR communication_source_basis.source_digest IS NULL THEN RETURN NULL; END IF;
 SELECT * INTO crm_match FROM public.canonical_external_business_reference_matches WHERE organization_id=org AND source_class='crm_field_service' AND source_key=crm_source AND consent_id=(crm_consent->>'id')::uuid AND reference_kind='estimate' AND external_reference=crm_reference ORDER BY revision DESC LIMIT 1;
 SELECT * INTO communication_match FROM public.canonical_external_business_reference_matches WHERE organization_id=org AND source_class='communication' AND source_key=communication_source AND consent_id=(communication_consent->>'id')::uuid AND reference_kind='estimate' AND external_reference=communication_reference_value ORDER BY revision DESC LIMIT 1;
 target_basis:=public.canonical_external_business_reference_target_basis(org,'estimate',estimate_value);
 IF target_basis IS NULL OR crm_match.id IS NULL OR crm_match.action<>'link' OR crm_match.target_id<>estimate_value OR crm_match.source_digest<>crm_source_basis.source_digest OR crm_match.target_digest<>target_basis->>'digest'
  OR communication_match.id IS NULL OR communication_match.action<>'link' OR communication_match.target_id<>estimate_value OR communication_match.source_digest<>communication_source_basis.source_digest OR communication_match.target_digest<>target_basis->>'digest' THEN RETURN NULL; END IF;
 WITH current_crm AS (SELECT DISTINCT ON(r.external_record_id)r.* FROM public.canonical_external_crm_field_service_import_records r WHERE r.organization_id=org AND r.source_key=crm_source AND r.consent_id=(crm_consent->>'id')::uuid ORDER BY r.external_record_id,r.revision DESC)
 SELECT count(*) INTO issued_total FROM current_crm WHERE state='active' AND record_type='issued_estimate' AND estimate_reference=crm_reference;
 WITH current_crm AS (SELECT DISTINCT ON(r.external_record_id)r.* FROM public.canonical_external_crm_field_service_import_records r WHERE r.organization_id=org AND r.source_key=crm_source AND r.consent_id=(crm_consent->>'id')::uuid ORDER BY r.external_record_id,r.revision DESC)
 SELECT * INTO issued_record FROM current_crm WHERE state='active' AND record_type='issued_estimate' AND estimate_reference=crm_reference ORDER BY external_record_id LIMIT 1;
 WITH current_crm AS (SELECT DISTINCT ON(r.external_record_id)r.* FROM public.canonical_external_crm_field_service_import_records r WHERE r.organization_id=org AND r.source_key=crm_source AND r.consent_id=(crm_consent->>'id')::uuid ORDER BY r.external_record_id,r.revision DESC), relevant AS (
  SELECT r.* FROM current_crm r WHERE r.state='active' AND ((r.record_type='issued_estimate' AND r.estimate_reference=crm_reference) OR (issued_total=1 AND issued_record.lead_reference IS NOT NULL AND r.record_type='lead' AND r.lead_reference=issued_record.lead_reference) OR (issued_total=1 AND issued_record.appointment_reference IS NOT NULL AND r.record_type='appointment' AND r.appointment_reference=issued_record.appointment_reference)))
 SELECT COALESCE(jsonb_agg(jsonb_build_object('externalRecordId',external_record_id,'revision',revision,'externalVersion',external_version,'recordType',record_type,'recordState',record_state,'occurredAt',occurred_at,'endedAt',ended_at,'evidenceClass',evidence_class,'sourceDigest',rtrim(source_digest)) ORDER BY external_record_id),'[]'::jsonb),count(*) FILTER(WHERE record_type='lead'),count(*) FILTER(WHERE record_type='appointment') INTO crm_records,lead_total,appointment_total FROM relevant;
 issued_value:=CASE WHEN issued_total=1 THEN jsonb_build_object('status','recorded','value',issued_record.record_state,'basis','source_recorded','occurredAt',issued_record.occurred_at,'endedAt',NULL,'evidenceClass',issued_record.evidence_class,'reason',NULL) ELSE public.canonical_external_customer_outcome_unavailable(CASE WHEN issued_total=0 THEN 'No current issued estimate record is available for this reviewed estimate.' ELSE 'More than one current issued estimate record needs source review.' END) END;
 lead_value:=CASE WHEN issued_total<>1 THEN public.canonical_external_customer_outcome_unavailable('A single current issued estimate record is required before the lead outcome can be related.') WHEN issued_record.lead_reference IS NULL THEN public.canonical_external_customer_outcome_unavailable('The issued estimate has no recorded lead reference.') WHEN lead_total=1 THEN (SELECT jsonb_build_object('status','recorded','value',r.record_state,'basis','source_recorded','occurredAt',r.occurred_at,'endedAt',NULL,'evidenceClass',r.evidence_class,'reason',NULL) FROM (SELECT DISTINCT ON(x.external_record_id)x.* FROM public.canonical_external_crm_field_service_import_records x WHERE x.organization_id=org AND x.source_key=crm_source AND x.consent_id=(crm_consent->>'id')::uuid ORDER BY x.external_record_id,x.revision DESC)r WHERE r.state='active' AND r.record_type='lead' AND r.lead_reference=issued_record.lead_reference) WHEN lead_total=0 THEN public.canonical_external_customer_outcome_unavailable('No current lead record is available for the issued estimate.') ELSE public.canonical_external_customer_outcome_unavailable('More than one current lead record needs source review.') END;
 appointment_value:=CASE WHEN issued_total<>1 THEN public.canonical_external_customer_outcome_unavailable('A single current issued estimate record is required before the appointment outcome can be related.') WHEN issued_record.appointment_reference IS NULL THEN public.canonical_external_customer_outcome_unavailable('The issued estimate has no recorded appointment reference.') WHEN appointment_total=1 THEN (SELECT jsonb_build_object('status','recorded','value',r.record_state,'basis','source_recorded','occurredAt',r.occurred_at,'endedAt',r.ended_at,'evidenceClass',r.evidence_class,'reason',NULL) FROM (SELECT DISTINCT ON(x.external_record_id)x.* FROM public.canonical_external_crm_field_service_import_records x WHERE x.organization_id=org AND x.source_key=crm_source AND x.consent_id=(crm_consent->>'id')::uuid ORDER BY x.external_record_id,x.revision DESC)r WHERE r.state='active' AND r.record_type='appointment' AND r.appointment_reference=issued_record.appointment_reference) WHEN appointment_total=0 THEN public.canonical_external_customer_outcome_unavailable('No current appointment record is available for the issued estimate.') ELSE public.canonical_external_customer_outcome_unavailable('More than one current appointment record needs source review.') END;
 WITH current_communication AS (SELECT DISTINCT ON(r.external_record_id)r.* FROM public.canonical_external_communication_import_records r WHERE r.organization_id=org AND r.source_key=communication_source AND r.consent_id=(communication_consent->>'id')::uuid ORDER BY r.external_record_id,r.revision DESC), relevant AS (SELECT * FROM current_communication WHERE state='active' AND estimate_reference=communication_reference_value)
 SELECT COALESCE(jsonb_agg(jsonb_build_object('externalRecordId',external_record_id,'revision',revision,'externalVersion',external_version,'recordType',record_type,'occurredAt',occurred_at,'evidenceClass',evidence_class,'sourceDigest',rtrim(source_digest)) ORDER BY external_record_id),'[]'::jsonb) INTO communication_records FROM relevant;
 WITH current_communication AS (SELECT DISTINCT ON(r.external_record_id)r.* FROM public.canonical_external_communication_import_records r WHERE r.organization_id=org AND r.source_key=communication_source AND r.consent_id=(communication_consent->>'id')::uuid ORDER BY r.external_record_id,r.revision DESC), candidates AS (
  SELECT external_record_id,occurred_at,evidence_class,intent_claim->>'value' value,intent_claim->>'basis' basis FROM current_communication WHERE state='active' AND estimate_reference=communication_reference_value AND record_type='communication' AND direction='inbound' AND intent_claim->>'status'='recorded' AND intent_claim->>'basis' IN ('customer_explicit','human_reviewed')
  UNION ALL SELECT external_record_id,occurred_at,evidence_class,satisfaction_claim->>'value',satisfaction_claim->>'basis' FROM current_communication WHERE state='active' AND estimate_reference=communication_reference_value AND record_type='satisfaction' AND satisfaction_claim->>'status'='recorded'), latest AS (SELECT * FROM candidates WHERE occurred_at=(SELECT max(occurred_at) FROM candidates))
 SELECT count(*),CASE WHEN count(*)=1 THEN jsonb_build_object('status','recorded','value',min(value),'basis',min(basis),'occurredAt',min(occurred_at),'endedAt',NULL,'evidenceClass',min(evidence_class),'reason',NULL) END INTO response_total,response_value FROM latest;
 IF response_total<>1 THEN response_value:=public.canonical_external_customer_outcome_unavailable(CASE WHEN response_total=0 THEN 'No current explicit customer response is available for this reviewed estimate.' ELSE 'Customer responses with the same latest time need source review.' END);END IF;
 outcome_value:=jsonb_build_object('lead',lead_value,'appointment',appointment_value,'issuedEstimate',issued_value,'customerResponse',response_value);
 digest_value:=public.canonical_completion_digest(jsonb_build_object('organizationId',org,'crmSourceKey',crm_source,'communicationSourceKey',communication_source,'estimateId',estimate_value,'crmMatchId',crm_match.id,'crmMatchDigest',rtrim(crm_match.canonical_digest),'communicationMatchId',communication_match.id,'communicationMatchDigest',rtrim(communication_match.canonical_digest),'targetDigest',target_basis->>'digest','crmRecords',crm_records,'communicationRecords',communication_records,'outcomes',outcome_value));
 RETURN jsonb_build_object('crmConsent',crm_consent,'communicationConsent',communication_consent,'crmMatchId',crm_match.id,'crmMatchRevision',crm_match.revision,'crmMatchDigest',rtrim(crm_match.canonical_digest),'communicationMatchId',communication_match.id,'communicationMatchRevision',communication_match.revision,'communicationMatchDigest',rtrim(communication_match.canonical_digest),'targetDigest',target_basis->>'digest','crmManifest',crm_records,'communicationManifest',communication_records,'outcomes',outcome_value,'sourceDigest',digest_value);
END $$;

CREATE FUNCTION public.canonical_external_customer_outcome_consent_read(org UUID,actor UUID,role_value TEXT,session_value UUID,crm_source TEXT,communication_source TEXT)
RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE row_value public.canonical_external_customer_outcome_consents%ROWTYPE;crm_current JSONB;communication_current JSONB;
BEGIN IF role_value IS NULL OR role_value NOT IN ('owner','admin') THEN RAISE EXCEPTION 'Customer outcome learning restricted' USING ERRCODE='42501';END IF;PERFORM public.canonical_field_execution_actor_authority(org,actor,role_value,session_value,NULL,FALSE);IF crm_source IS NULL OR crm_source!~'^[a-z0-9][a-z0-9._-]{1,63}$' OR communication_source IS NULL OR communication_source!~'^[a-z0-9][a-z0-9._-]{1,63}$' THEN RAISE EXCEPTION 'Customer outcome consent read invalid' USING ERRCODE='22023';END IF;crm_current:=public.canonical_external_business_source_consent_basis(org,'crm_field_service',crm_source);communication_current:=public.canonical_external_business_source_consent_basis(org,'communication',communication_source);SELECT * INTO row_value FROM public.canonical_external_customer_outcome_consents WHERE organization_id=org AND crm_source_key=crm_source AND communication_source_key=communication_source ORDER BY revision DESC LIMIT 1;RETURN jsonb_build_object('crmSourceKey',crm_source,'communicationSourceKey',communication_source,'current',CASE WHEN row_value.id IS NULL THEN NULL ELSE public.canonical_external_customer_outcome_consent_projection(row_value,crm_current,communication_current) END,'sourcePermissionsAvailable',crm_current IS NOT NULL AND communication_current IS NOT NULL,'consumptionBoundary','Customer outcome learning records advice only and changes no customer, lead, appointment, estimate, schedule, price or policy.');END $$;

CREATE FUNCTION public.canonical_external_customer_outcome_consent_mutate(org UUID,actor UUID,role_value TEXT,session_value UUID,csrf TEXT,key_value TEXT,crm_source TEXT,communication_source TEXT,body JSONB)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE authority JSONB;current_row public.canonical_external_customer_outcome_consents%ROWTYPE;replay public.canonical_external_customer_outcome_consents%ROWTYPE;inserted public.canonical_external_customer_outcome_consents%ROWTYPE;crm_current JSONB;communication_current JSONB;key_hash TEXT;request_hash TEXT;digest_value TEXT;next_revision BIGINT;
BEGIN
 IF current_setting('transaction_isolation')<>'serializable' THEN RAISE EXCEPTION 'Serializable required' USING ERRCODE='25001';END IF;IF role_value IS NULL OR role_value NOT IN ('owner','admin') THEN RAISE EXCEPTION 'Customer outcome learning restricted' USING ERRCODE='42501';END IF;PERFORM 1 FROM public.subscriptions WHERE organization_id=org FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'Subscription unavailable' USING ERRCODE='42501';END IF;authority:=public.canonical_field_execution_actor_authority(org,actor,role_value,session_value,csrf,TRUE);
 IF crm_source IS NULL OR crm_source!~'^[a-z0-9][a-z0-9._-]{1,63}$' OR communication_source IS NULL OR communication_source!~'^[a-z0-9][a-z0-9._-]{1,63}$' OR key_value IS NULL OR key_value!~'^[A-Za-z0-9._:-]{16,128}$' OR octet_length(body::text)>8192 OR public.canonical_field_evidence_object_keys_exact(body,ARRAY['action','expectedRevision','expectedDigest','reason','confirmed','confirmationVersion']) IS NOT TRUE OR body->>'action' NOT IN ('grant','revoke') OR jsonb_typeof(body->'expectedRevision')<>'number' OR (body->>'expectedRevision')!~'^(0|[1-9][0-9]{0,3}|10000)$' OR body->>'expectedDigest'!~'^(none|[0-9a-f]{64})$' OR (((body->>'expectedRevision')::bigint=0)<>(body->>'expectedDigest'='none')) OR public.canonical_learning_text_valid(body->>'reason',2000) IS NOT TRUE OR body->'confirmed' IS DISTINCT FROM 'true'::jsonb OR body->>'confirmationVersion'<>'m25-external-customer-outcome-consent-v1' THEN RAISE EXCEPTION 'Customer outcome consent invalid' USING ERRCODE='22023';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(org::text||':external-customer-outcome:'||crm_source||':'||communication_source,0));key_hash:=encode(sha256(convert_to(key_value,'UTF8')),'hex');request_hash:=public.canonical_completion_digest(jsonb_build_object('organizationId',org,'actorUserId',actor,'crmSourceKey',crm_source,'communicationSourceKey',communication_source,'body',body));
 SELECT * INTO replay FROM public.canonical_external_customer_outcome_consents WHERE organization_id=org AND actor_user_id=actor AND request_key_hash=key_hash;IF FOUND THEN IF rtrim(replay.request_digest)<>request_hash THEN RAISE EXCEPTION 'Customer outcome consent key conflict' USING ERRCODE='23505';END IF;crm_current:=public.canonical_external_business_source_consent_basis(org,'crm_field_service',crm_source);communication_current:=public.canonical_external_business_source_consent_basis(org,'communication',communication_source);RETURN jsonb_build_object('consent',public.canonical_external_customer_outcome_consent_projection(replay,crm_current,communication_current),'replayed',TRUE);END IF;
 SELECT * INTO current_row FROM public.canonical_external_customer_outcome_consents WHERE organization_id=org AND crm_source_key=crm_source AND communication_source_key=communication_source ORDER BY revision DESC LIMIT 1 FOR UPDATE;IF (body->>'expectedRevision')::bigint<>COALESCE(current_row.revision,0) OR body->>'expectedDigest'<>COALESCE(rtrim(current_row.canonical_digest),'none') THEN RAISE EXCEPTION 'Customer outcome consent changed' USING ERRCODE='40001';END IF;
 crm_current:=public.canonical_external_business_source_consent_basis(org,'crm_field_service',crm_source);communication_current:=public.canonical_external_business_source_consent_basis(org,'communication',communication_source);IF body->>'action'='grant' AND (crm_current IS NULL OR communication_current IS NULL) THEN RAISE EXCEPTION 'Current source permissions required' USING ERRCODE='P0002',CONSTRAINT='customer_outcome_consent_unavailable';END IF;
 next_revision:=COALESCE(current_row.revision,0)+1;digest_value:=public.canonical_completion_digest(jsonb_build_object('organizationId',org,'crmSourceKey',crm_source,'communicationSourceKey',communication_source,'revision',next_revision,'previousId',current_row.id,'action',body->>'action','crmSourceConsentId',CASE WHEN body->>'action'='grant' THEN crm_current->>'id' END,'crmSourceConsentRevision',CASE WHEN body->>'action'='grant' THEN (crm_current->>'revision')::bigint END,'crmSourceConsentDigest',CASE WHEN body->>'action'='grant' THEN crm_current->>'digest' END,'communicationSourceConsentId',CASE WHEN body->>'action'='grant' THEN communication_current->>'id' END,'communicationSourceConsentRevision',CASE WHEN body->>'action'='grant' THEN (communication_current->>'revision')::bigint END,'communicationSourceConsentDigest',CASE WHEN body->>'action'='grant' THEN communication_current->>'digest' END,'actorUserId',actor,'reason',body->>'reason','confirmationVersion',body->>'confirmationVersion','requestDigest',request_hash));
 INSERT INTO public.canonical_external_customer_outcome_consents(organization_id,crm_source_key,communication_source_key,revision,previous_id,action,crm_source_consent_id,crm_source_consent_revision,crm_source_consent_digest,communication_source_consent_id,communication_source_consent_revision,communication_source_consent_digest,actor_user_id,membership_id,auth_session_id,reason,confirmed,confirmation_version,request_key_hash,request_digest,canonical_digest)
 VALUES(org,crm_source,communication_source,next_revision,current_row.id,body->>'action',CASE WHEN body->>'action'='grant' THEN (crm_current->>'id')::uuid END,CASE WHEN body->>'action'='grant' THEN (crm_current->>'revision')::bigint END,CASE WHEN body->>'action'='grant' THEN crm_current->>'digest' END,CASE WHEN body->>'action'='grant' THEN (communication_current->>'id')::uuid END,CASE WHEN body->>'action'='grant' THEN (communication_current->>'revision')::bigint END,CASE WHEN body->>'action'='grant' THEN communication_current->>'digest' END,actor,(authority->>'membershipId')::uuid,session_value,body->>'reason',TRUE,body->>'confirmationVersion',key_hash,request_hash,digest_value) RETURNING * INTO inserted;RETURN jsonb_build_object('consent',public.canonical_external_customer_outcome_consent_projection(inserted,crm_current,communication_current),'replayed',FALSE);END $$;

CREATE FUNCTION public.canonical_external_customer_outcome_projection(value public.canonical_external_customer_outcome_observations,basis JSONB,consent_value public.canonical_external_customer_outcome_consents,crm_current JSONB,communication_current JSONB)
RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE active_value BOOLEAN;fresh_value BOOLEAN;
BEGIN active_value:=COALESCE(consent_value.id=value.consent_id AND consent_value.action='grant' AND crm_current->>'id'=consent_value.crm_source_consent_id::text AND crm_current->>'digest'=rtrim(consent_value.crm_source_consent_digest) AND communication_current->>'id'=consent_value.communication_source_consent_id::text AND communication_current->>'digest'=rtrim(consent_value.communication_source_consent_digest),FALSE);IF NOT active_value THEN RETURN jsonb_build_object('id',value.id,'revision',value.revision,'fresh',FALSE,'hiddenByConsent',TRUE,'advisoryAvailable',FALSE,'refreshRequired',TRUE,'outcomes',jsonb_build_object('lead',public.canonical_external_customer_outcome_unavailable('Customer outcome advice is hidden because permission is inactive.'),'appointment',public.canonical_external_customer_outcome_unavailable('Customer outcome advice is hidden because permission is inactive.'),'issuedEstimate',public.canonical_external_customer_outcome_unavailable('Customer outcome advice is hidden because permission is inactive.'),'customerResponse',public.canonical_external_customer_outcome_unavailable('Customer outcome advice is hidden because permission is inactive.')),'digest',rtrim(value.canonical_digest),'createdAt',value.created_at);END IF;fresh_value:=basis IS NOT NULL AND basis->>'sourceDigest'=value.source_digest;RETURN jsonb_build_object('id',value.id,'crmSourceKey',value.crm_source_key,'communicationSourceKey',value.communication_source_key,'estimateId',value.estimate_id,'crmEstimateReference',value.crm_estimate_reference,'communicationEstimateReference',value.communication_estimate_reference,'revision',value.revision,'previousId',value.previous_id,'consentId',value.consent_id,'consentRevision',value.consent_revision,'consentDigest',rtrim(value.consent_digest),'crmMatchId',value.crm_match_id,'crmMatchRevision',value.crm_match_revision,'crmMatchDigest',rtrim(value.crm_match_digest),'communicationMatchId',value.communication_match_id,'communicationMatchRevision',value.communication_match_revision,'communicationMatchDigest',rtrim(value.communication_match_digest),'targetDigest',rtrim(value.target_digest),'crmManifest',value.crm_manifest,'communicationManifest',value.communication_manifest,'sourceDigest',rtrim(value.source_digest),'outcomes',CASE WHEN fresh_value THEN value.outcomes ELSE jsonb_build_object('lead',public.canonical_external_customer_outcome_unavailable('Current evidence or reviewed links changed. Refresh before using this advice.'),'appointment',public.canonical_external_customer_outcome_unavailable('Current evidence or reviewed links changed. Refresh before using this advice.'),'issuedEstimate',public.canonical_external_customer_outcome_unavailable('Current evidence or reviewed links changed. Refresh before using this advice.'),'customerResponse',public.canonical_external_customer_outcome_unavailable('Current evidence or reviewed links changed. Refresh before using this advice.')) END,'fresh',fresh_value,'hiddenByConsent',FALSE,'advisoryAvailable',fresh_value,'refreshRequired',NOT fresh_value,'reason',value.reason,'confirmed',value.confirmed,'confirmationVersion',value.confirmation_version,'calculationVersion',value.calculation_version,'digest',rtrim(value.canonical_digest),'createdAt',value.created_at,'adoptionBoundary','No customer, lead, appointment, estimate, schedule, price, message, source record or company policy was changed.');END $$;

CREATE FUNCTION public.canonical_external_customer_outcome_observation_guard() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE basis JSONB;consent_value public.canonical_external_customer_outcome_consents%ROWTYPE;crm_current JSONB;communication_current JSONB;previous_row public.canonical_external_customer_outcome_observations%ROWTYPE;expected_digest TEXT;
BEGIN SELECT * INTO consent_value FROM public.canonical_external_customer_outcome_consents WHERE id=NEW.consent_id AND organization_id=NEW.organization_id;crm_current:=public.canonical_external_business_source_consent_basis(NEW.organization_id,'crm_field_service',NEW.crm_source_key);communication_current:=public.canonical_external_business_source_consent_basis(NEW.organization_id,'communication',NEW.communication_source_key);basis:=public.canonical_external_customer_outcome_basis(NEW.organization_id,NEW.crm_source_key,NEW.communication_source_key,NEW.estimate_id,NEW.crm_estimate_reference,NEW.communication_estimate_reference);IF consent_value.id IS NULL OR consent_value.action<>'grant' OR consent_value.revision<>NEW.consent_revision OR rtrim(consent_value.canonical_digest)<>rtrim(NEW.consent_digest) OR crm_current IS NULL OR communication_current IS NULL OR consent_value.crm_source_consent_id<>(crm_current->>'id')::uuid OR rtrim(consent_value.crm_source_consent_digest)<>crm_current->>'digest' OR consent_value.communication_source_consent_id<>(communication_current->>'id')::uuid OR rtrim(consent_value.communication_source_consent_digest)<>communication_current->>'digest' OR basis IS NULL OR basis->>'sourceDigest'<>NEW.source_digest OR basis->'outcomes'<>NEW.outcomes OR basis->'crmManifest'<>NEW.crm_manifest OR basis->'communicationManifest'<>NEW.communication_manifest OR (basis->>'crmMatchId')::uuid<>NEW.crm_match_id OR (basis->>'crmMatchRevision')::bigint<>NEW.crm_match_revision OR basis->>'crmMatchDigest'<>rtrim(NEW.crm_match_digest) OR (basis->>'communicationMatchId')::uuid<>NEW.communication_match_id OR (basis->>'communicationMatchRevision')::bigint<>NEW.communication_match_revision OR basis->>'communicationMatchDigest'<>rtrim(NEW.communication_match_digest) OR basis->>'targetDigest'<>NEW.target_digest THEN RAISE EXCEPTION 'Customer outcome lineage invalid' USING ERRCODE='23514';END IF;IF NEW.revision>1 THEN SELECT * INTO previous_row FROM public.canonical_external_customer_outcome_observations WHERE organization_id=NEW.organization_id AND crm_source_key=NEW.crm_source_key AND communication_source_key=NEW.communication_source_key AND estimate_id=NEW.estimate_id AND crm_estimate_reference=NEW.crm_estimate_reference AND communication_estimate_reference=NEW.communication_estimate_reference AND id=NEW.previous_id;IF previous_row.id IS NULL OR previous_row.revision+1<>NEW.revision THEN RAISE EXCEPTION 'Customer outcome observation revision invalid' USING ERRCODE='23514';END IF;END IF;expected_digest:=public.canonical_completion_digest(jsonb_build_object('organizationId',NEW.organization_id,'crmSourceKey',NEW.crm_source_key,'communicationSourceKey',NEW.communication_source_key,'estimateId',NEW.estimate_id,'crmEstimateReference',NEW.crm_estimate_reference,'communicationEstimateReference',NEW.communication_estimate_reference,'revision',NEW.revision,'previousId',NEW.previous_id,'consentId',NEW.consent_id,'consentRevision',NEW.consent_revision,'consentDigest',rtrim(NEW.consent_digest),'crmMatchId',NEW.crm_match_id,'crmMatchRevision',NEW.crm_match_revision,'crmMatchDigest',rtrim(NEW.crm_match_digest),'communicationMatchId',NEW.communication_match_id,'communicationMatchRevision',NEW.communication_match_revision,'communicationMatchDigest',rtrim(NEW.communication_match_digest),'targetDigest',rtrim(NEW.target_digest),'crmManifest',NEW.crm_manifest,'communicationManifest',NEW.communication_manifest,'sourceDigest',NEW.source_digest,'outcomes',NEW.outcomes,'actorUserId',NEW.actor_user_id,'confirmationVersion',NEW.confirmation_version,'calculationVersion',NEW.calculation_version,'requestDigest',rtrim(NEW.request_digest)));IF rtrim(NEW.canonical_digest)<>expected_digest THEN RAISE EXCEPTION 'Customer outcome observation digest invalid' USING ERRCODE='23514';END IF;RETURN NEW;END $$;
CREATE TRIGGER canonical_external_customer_outcome_observation_guard BEFORE INSERT ON public.canonical_external_customer_outcome_observations FOR EACH ROW EXECUTE FUNCTION public.canonical_external_customer_outcome_observation_guard();

CREATE FUNCTION public.canonical_external_customer_outcome_observe(org UUID,actor UUID,role_value TEXT,session_value UUID,csrf TEXT,key_value TEXT,crm_source TEXT,communication_source TEXT,estimate_value UUID,crm_reference TEXT,communication_reference TEXT,expected_consent_revision BIGINT,expected_consent_digest TEXT,reason_value TEXT,confirmed_value BOOLEAN,confirmation_version_value TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE authority JSONB;consent_value public.canonical_external_customer_outcome_consents%ROWTYPE;current_row public.canonical_external_customer_outcome_observations%ROWTYPE;replay public.canonical_external_customer_outcome_observations%ROWTYPE;inserted public.canonical_external_customer_outcome_observations%ROWTYPE;crm_current JSONB;communication_current JSONB;basis JSONB;key_hash TEXT;request_hash TEXT;digest_value TEXT;next_revision BIGINT;
BEGIN IF current_setting('transaction_isolation')<>'serializable' THEN RAISE EXCEPTION 'Serializable required' USING ERRCODE='25001';END IF;IF role_value IS NULL OR role_value NOT IN ('owner','admin') THEN RAISE EXCEPTION 'Customer outcome learning restricted' USING ERRCODE='42501';END IF;PERFORM 1 FROM public.subscriptions WHERE organization_id=org FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'Subscription unavailable' USING ERRCODE='42501';END IF;authority:=public.canonical_field_execution_actor_authority(org,actor,role_value,session_value,csrf,TRUE);
 IF crm_source IS NULL OR crm_source!~'^[a-z0-9][a-z0-9._-]{1,63}$' OR communication_source IS NULL OR communication_source!~'^[a-z0-9][a-z0-9._-]{1,63}$' OR crm_reference IS NULL OR length(crm_reference) NOT BETWEEN 1 AND 128 OR crm_reference!~'^[!-~]+$' OR communication_reference!~'^ref_[0-9a-f]{64}$' OR key_value IS NULL OR key_value!~'^[A-Za-z0-9._:-]{16,128}$' OR expected_consent_revision NOT BETWEEN 1 AND 10000 OR expected_consent_digest!~'^[0-9a-f]{64}$' OR public.canonical_learning_text_valid(reason_value,2000) IS NOT TRUE OR confirmed_value IS DISTINCT FROM TRUE OR confirmation_version_value<>'m25-external-customer-outcome-observation-v1' THEN RAISE EXCEPTION 'Customer outcome observation invalid' USING ERRCODE='22023';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(org::text||':external-customer-outcome:'||crm_source||':'||communication_source,0));PERFORM pg_advisory_xact_lock(hashtextextended(org::text||':external-customer-outcome-observation:'||estimate_value::text||':'||crm_reference||':'||communication_reference,0));key_hash:=encode(sha256(convert_to(key_value,'UTF8')),'hex');request_hash:=public.canonical_completion_digest(jsonb_build_object('organizationId',org,'actorUserId',actor,'crmSourceKey',crm_source,'communicationSourceKey',communication_source,'estimateId',estimate_value,'crmEstimateReference',crm_reference,'communicationEstimateReference',communication_reference,'expectedConsentRevision',expected_consent_revision,'expectedConsentDigest',expected_consent_digest,'reason',reason_value,'confirmed',confirmed_value,'confirmationVersion',confirmation_version_value));
 SELECT * INTO replay FROM public.canonical_external_customer_outcome_observations WHERE organization_id=org AND actor_user_id=actor AND request_key_hash=key_hash;IF FOUND THEN IF rtrim(replay.request_digest)<>request_hash THEN RAISE EXCEPTION 'Customer outcome observation key conflict' USING ERRCODE='23505';END IF;SELECT * INTO consent_value FROM public.canonical_external_customer_outcome_consents WHERE organization_id=org AND crm_source_key=crm_source AND communication_source_key=communication_source ORDER BY revision DESC LIMIT 1;crm_current:=public.canonical_external_business_source_consent_basis(org,'crm_field_service',crm_source);communication_current:=public.canonical_external_business_source_consent_basis(org,'communication',communication_source);basis:=public.canonical_external_customer_outcome_basis(org,crm_source,communication_source,replay.estimate_id,replay.crm_estimate_reference,replay.communication_estimate_reference);RETURN jsonb_build_object('observation',public.canonical_external_customer_outcome_projection(replay,basis,consent_value,crm_current,communication_current),'replayed',TRUE);END IF;
 SELECT * INTO consent_value FROM public.canonical_external_customer_outcome_consents WHERE organization_id=org AND crm_source_key=crm_source AND communication_source_key=communication_source ORDER BY revision DESC LIMIT 1;crm_current:=public.canonical_external_business_source_consent_basis(org,'crm_field_service',crm_source);communication_current:=public.canonical_external_business_source_consent_basis(org,'communication',communication_source);IF consent_value.id IS NULL OR consent_value.action<>'grant' OR crm_current IS NULL OR communication_current IS NULL OR consent_value.crm_source_consent_id<>(crm_current->>'id')::uuid OR rtrim(consent_value.crm_source_consent_digest)<>crm_current->>'digest' OR consent_value.communication_source_consent_id<>(communication_current->>'id')::uuid OR rtrim(consent_value.communication_source_consent_digest)<>communication_current->>'digest' THEN RAISE EXCEPTION 'Current source and outcome permissions required' USING ERRCODE='P0002',CONSTRAINT='customer_outcome_consent_unavailable';END IF;IF consent_value.revision<>expected_consent_revision OR rtrim(consent_value.canonical_digest)<>expected_consent_digest THEN RAISE EXCEPTION 'Customer outcome consent changed' USING ERRCODE='40001';END IF;
 basis:=public.canonical_external_customer_outcome_basis(org,crm_source,communication_source,estimate_value,crm_reference,communication_reference);IF basis IS NULL THEN RAISE EXCEPTION 'Current reviewed estimate links and evidence required' USING ERRCODE='P0002',CONSTRAINT='customer_outcome_lineage_unavailable';END IF;
 SELECT * INTO current_row FROM public.canonical_external_customer_outcome_observations WHERE organization_id=org AND crm_source_key=crm_source AND communication_source_key=communication_source AND estimate_id=estimate_value AND crm_estimate_reference=crm_reference AND communication_estimate_reference=communication_reference ORDER BY revision DESC LIMIT 1 FOR UPDATE;IF current_row.id IS NOT NULL AND current_row.consent_id=consent_value.id AND current_row.source_digest=basis->>'sourceDigest' THEN RAISE EXCEPTION 'Current customer outcome already recorded' USING ERRCODE='22023',CONSTRAINT='customer_outcome_already_current';END IF;
 next_revision:=COALESCE(current_row.revision,0)+1;digest_value:=public.canonical_completion_digest(jsonb_build_object('organizationId',org,'crmSourceKey',crm_source,'communicationSourceKey',communication_source,'estimateId',estimate_value,'crmEstimateReference',crm_reference,'communicationEstimateReference',communication_reference,'revision',next_revision,'previousId',current_row.id,'consentId',consent_value.id,'consentRevision',consent_value.revision,'consentDigest',rtrim(consent_value.canonical_digest),'crmMatchId',basis->>'crmMatchId','crmMatchRevision',(basis->>'crmMatchRevision')::bigint,'crmMatchDigest',basis->>'crmMatchDigest','communicationMatchId',basis->>'communicationMatchId','communicationMatchRevision',(basis->>'communicationMatchRevision')::bigint,'communicationMatchDigest',basis->>'communicationMatchDigest','targetDigest',basis->>'targetDigest','crmManifest',basis->'crmManifest','communicationManifest',basis->'communicationManifest','sourceDigest',basis->>'sourceDigest','outcomes',basis->'outcomes','actorUserId',actor,'confirmationVersion',confirmation_version_value,'calculationVersion','m25-external-customer-outcome-v1','requestDigest',request_hash));
 INSERT INTO public.canonical_external_customer_outcome_observations(organization_id,crm_source_key,communication_source_key,estimate_id,crm_estimate_reference,communication_estimate_reference,revision,previous_id,consent_id,consent_revision,consent_digest,crm_match_id,crm_match_revision,crm_match_digest,communication_match_id,communication_match_revision,communication_match_digest,target_digest,crm_manifest,communication_manifest,source_digest,outcomes,actor_user_id,membership_id,auth_session_id,reason,confirmed,confirmation_version,calculation_version,request_key_hash,request_digest,canonical_digest)
 VALUES(org,crm_source,communication_source,estimate_value,crm_reference,communication_reference,next_revision,current_row.id,consent_value.id,consent_value.revision,rtrim(consent_value.canonical_digest),(basis->>'crmMatchId')::uuid,(basis->>'crmMatchRevision')::bigint,basis->>'crmMatchDigest',(basis->>'communicationMatchId')::uuid,(basis->>'communicationMatchRevision')::bigint,basis->>'communicationMatchDigest',basis->>'targetDigest',basis->'crmManifest',basis->'communicationManifest',basis->>'sourceDigest',basis->'outcomes',actor,(authority->>'membershipId')::uuid,session_value,reason_value,TRUE,confirmation_version_value,'m25-external-customer-outcome-v1',key_hash,request_hash,digest_value) RETURNING * INTO inserted;RETURN jsonb_build_object('observation',public.canonical_external_customer_outcome_projection(inserted,basis,consent_value,crm_current,communication_current),'replayed',FALSE);END $$;

CREATE FUNCTION public.canonical_external_customer_outcome_read(org UUID,actor UUID,role_value TEXT,session_value UUID,crm_source TEXT,communication_source TEXT,estimate_value UUID,crm_reference TEXT,communication_reference TEXT)
RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE consent_value public.canonical_external_customer_outcome_consents%ROWTYPE;current_row public.canonical_external_customer_outcome_observations%ROWTYPE;crm_current JSONB;communication_current JSONB;basis JSONB;history JSONB;total BIGINT;active_value BOOLEAN;
BEGIN IF role_value IS NULL OR role_value NOT IN ('owner','admin') THEN RAISE EXCEPTION 'Customer outcome learning restricted' USING ERRCODE='42501';END IF;PERFORM public.canonical_field_execution_actor_authority(org,actor,role_value,session_value,NULL,FALSE);IF crm_source IS NULL OR crm_source!~'^[a-z0-9][a-z0-9._-]{1,63}$' OR communication_source IS NULL OR communication_source!~'^[a-z0-9][a-z0-9._-]{1,63}$' OR crm_reference IS NULL OR length(crm_reference) NOT BETWEEN 1 AND 128 OR crm_reference!~'^[!-~]+$' OR communication_reference!~'^ref_[0-9a-f]{64}$' THEN RAISE EXCEPTION 'Customer outcome read invalid' USING ERRCODE='22023';END IF;SELECT * INTO consent_value FROM public.canonical_external_customer_outcome_consents WHERE organization_id=org AND crm_source_key=crm_source AND communication_source_key=communication_source ORDER BY revision DESC LIMIT 1;crm_current:=public.canonical_external_business_source_consent_basis(org,'crm_field_service',crm_source);communication_current:=public.canonical_external_business_source_consent_basis(org,'communication',communication_source);active_value:=COALESCE(consent_value.id IS NOT NULL AND consent_value.action='grant' AND crm_current->>'id'=consent_value.crm_source_consent_id::text AND crm_current->>'digest'=rtrim(consent_value.crm_source_consent_digest) AND communication_current->>'id'=consent_value.communication_source_consent_id::text AND communication_current->>'digest'=rtrim(consent_value.communication_source_consent_digest),FALSE);IF NOT active_value THEN RETURN jsonb_build_object('crmSourceKey',crm_source,'communicationSourceKey',communication_source,'activeConsent',FALSE,'current',NULL,'history','[]'::jsonb,'total',0,'truncated',FALSE,'consumptionBoundary','Customer outcome advice is unavailable until permission is granted for both current sources.');END IF;basis:=public.canonical_external_customer_outcome_basis(org,crm_source,communication_source,estimate_value,crm_reference,communication_reference);SELECT * INTO current_row FROM public.canonical_external_customer_outcome_observations WHERE organization_id=org AND crm_source_key=crm_source AND communication_source_key=communication_source AND estimate_id=estimate_value AND crm_estimate_reference=crm_reference AND communication_estimate_reference=communication_reference ORDER BY revision DESC LIMIT 1;SELECT count(*) INTO total FROM public.canonical_external_customer_outcome_observations WHERE organization_id=org AND crm_source_key=crm_source AND communication_source_key=communication_source AND estimate_id=estimate_value AND crm_estimate_reference=crm_reference AND communication_estimate_reference=communication_reference;SELECT COALESCE(jsonb_agg(public.canonical_external_customer_outcome_projection(x,basis,consent_value,crm_current,communication_current) ORDER BY revision DESC),'[]'::jsonb) INTO history FROM(SELECT * FROM public.canonical_external_customer_outcome_observations WHERE organization_id=org AND crm_source_key=crm_source AND communication_source_key=communication_source AND estimate_id=estimate_value AND crm_estimate_reference=crm_reference AND communication_estimate_reference=communication_reference ORDER BY revision DESC LIMIT 20)x;RETURN jsonb_build_object('crmSourceKey',crm_source,'communicationSourceKey',communication_source,'activeConsent',TRUE,'current',CASE WHEN current_row.id IS NULL THEN NULL ELSE public.canonical_external_customer_outcome_projection(current_row,basis,consent_value,crm_current,communication_current) END,'history',history,'total',total,'truncated',total>20,'consumptionBoundary','Recorded outcomes are advisory. Delivery status and provider classifications do not become verified customer responses.');END $$;

REVOKE ALL ON TABLE public.canonical_external_customer_outcome_consents,public.canonical_external_customer_outcome_observations FROM PUBLIC;
REVOKE ALL ON FUNCTION public.canonical_external_customer_outcome_immutable() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.canonical_external_customer_outcome_dimension_valid(JSONB,TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.canonical_external_customer_outcomes_valid(JSONB) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.canonical_external_customer_outcome_unavailable(TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.canonical_external_customer_outcome_consent_projection(public.canonical_external_customer_outcome_consents,JSONB,JSONB) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.canonical_external_customer_outcome_consent_guard() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.canonical_external_customer_outcome_basis(UUID,TEXT,TEXT,UUID,TEXT,TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.canonical_external_customer_outcome_consent_read(UUID,UUID,TEXT,UUID,TEXT,TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.canonical_external_customer_outcome_consent_mutate(UUID,UUID,TEXT,UUID,TEXT,TEXT,TEXT,TEXT,JSONB) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.canonical_external_customer_outcome_projection(public.canonical_external_customer_outcome_observations,JSONB,public.canonical_external_customer_outcome_consents,JSONB,JSONB) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.canonical_external_customer_outcome_observation_guard() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.canonical_external_customer_outcome_observe(UUID,UUID,TEXT,UUID,TEXT,TEXT,TEXT,TEXT,UUID,TEXT,TEXT,BIGINT,TEXT,TEXT,BOOLEAN,TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.canonical_external_customer_outcome_read(UUID,UUID,TEXT,UUID,TEXT,TEXT,UUID,TEXT,TEXT) FROM PUBLIC;
